with recursive candidates(i,name) as (select 1,data_text_trim_v1(?1) union all select i+1,data_text_trim_end_matches_v1(data_text_prefix_v1(?1,500-data_text_char_count_v1('`旧归类-'||(i+1))),'`')||'`旧归类-'||(i+1) from candidates where exists(select 1 from concepts where deleted_at is null and trim(label)=name)) select name from candidates where not exists(select 1 from concepts where deleted_at is null and trim(label)=name) limit 1